import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"Design Goals","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/intro/design.md","filePath":"en/development/intro/design.md","lastUpdated":1769206051000}`),a={name:`en/development/intro/design.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to “Design Goals”">​</a></h1><ul><li>The Xray core provides a platform that supports necessary network proxy functions, upon which secondary development can be conducted to provide a better user experience.</li><li>Cross-platform support is the primary principle to reduce the cost of secondary development.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><p><img src="/assets/framework.Bf6xCZ4u.png" alt="Architecture" width="1206" height="922"></p><p>The core is divided into three layers: Application Layer, Proxy Layer, and Transport Layer.</p><p>Each layer contains several modules. Modules are independent of each other, and modules of the same type can be seamlessly replaced.</p><h3 id="application-layer" tabindex="-1">Application Layer <a class="header-anchor" href="#application-layer" aria-label="Permalink to “Application Layer”">​</a></h3><p>The Application Layer contains common functions used in the Proxy Layer. These functions are abstracted to be reused across different proxy modules.</p><p>Modules in the Application Layer should be pure software implementations, independent of hardware or platform-specific technologies.</p><p>Important module list:</p><ul><li><strong>Dispatcher</strong>: Used to transmit data received by the inbound proxy to the outbound proxy.</li><li><strong>Router</strong>: Routing module, see <a href="./../../config/routing.html">Routing Configuration</a> for details.</li><li><strong>DNS</strong>: Built-in DNS server module.</li><li><strong>Proxy Manager</strong>: Manages proxies.</li></ul><h3 id="proxy-layer" tabindex="-1">Proxy Layer <a class="header-anchor" href="#proxy-layer" aria-label="Permalink to “Proxy Layer”">​</a></h3><p>The Proxy Layer is divided into two parts: Inbound Proxy and Outbound Proxy.</p><p>The two parts are independent of each other. An inbound proxy does not depend on a specific outbound proxy, and vice versa.</p><h4 id="inbound-proxy" tabindex="-1">Inbound Proxy <a class="header-anchor" href="#inbound-proxy" aria-label="Permalink to “Inbound Proxy”">​</a></h4><ul><li>Implements the <a href="https://github.com/xtls/Xray-core/blob/main/proxy/proxy.go" target="_blank" rel="noreferrer">proxy.Inbound</a> interface.</li></ul><h4 id="outbound-proxy" tabindex="-1">Outbound Proxy <a class="header-anchor" href="#outbound-proxy" aria-label="Permalink to “Outbound Proxy”">​</a></h4><ul><li>Implements the <a href="https://github.com/xtls/Xray-core/blob/main/proxy/proxy.go" target="_blank" rel="noreferrer">proxy.Outbound</a> interface.</li></ul><h3 id="transport-layer" tabindex="-1">Transport Layer <a class="header-anchor" href="#transport-layer" aria-label="Permalink to “Transport Layer”">​</a></h3><p>The Transport Layer provides tool modules related to network data transmission.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};